//! Native ABI v1: fixed little-endian request and bounded typed response. No raw save in replies.
//! The future WASM bridge transfers OPEN bytes separately and calls dispatch_frame on one session.
use crate::{session::*,native::ModelState,projection::{DetailKind,DetailRow},Error,envelope::Version};
pub const MAGIC:[u8;4]=*b"HKS1";
pub const HEADER:usize=78; // magic, opcode, id, runtime, generation, revision, source-present + digest
pub const MAX_REPLY:usize=32*1024;
fn kind(b:u8)->Result<InputKind,SessionError>{match b{1=>Ok(InputKind::Zip),2=>Ok(InputKind::Slot),3=>Ok(InputKind::Account),_=>Err(SessionError::Protocol)}}
fn domain(b:u8)->Result<Domain,SessionError>{match b{1=>Ok(Domain::SlotAchievement),2=>Ok(Domain::SlotCounter),3=>Ok(Domain::CollectionHistory),4=>Ok(Domain::Celebration),5=>Ok(Domain::AccountAchievement),6=>Ok(Domain::AccountCounter),7=>Ok(Domain::Inventory),8=>Ok(Domain::DeprecatedCollection),_=>Err(SessionError::Protocol)}}
fn kind_code(k:InputKind)->u8{match k{InputKind::Zip=>1,InputKind::Slot=>2,InputKind::Account=>3}}
fn domain_code(d:Domain)->u8{match d{Domain::SlotAchievement=>1,Domain::SlotCounter=>2,Domain::CollectionHistory=>3,Domain::Celebration=>4,Domain::AccountAchievement=>5,Domain::AccountCounter=>6,Domain::Inventory=>7,Domain::DeprecatedCollection=>8}}
fn detail_kind(b:u8)->Result<DetailKind,SessionError>{match b{1=>Ok(DetailKind::CounterValues),2=>Ok(DetailKind::CounterGuids),3=>Ok(DetailKind::CelebrationGuids),_=>Err(SessionError::Protocol)}}
fn detail_code(k:DetailKind)->u8{match k{DetailKind::CounterValues=>1,DetailKind::CounterGuids=>2,DetailKind::CelebrationGuids=>3}}
fn parse(frame:&[u8],input:Option<Vec<u8>>)->Result<Request,SessionError>{if frame.len()<HEADER||frame[..4]!=MAGIC{return Err(SessionError::Protocol)}let opcode=frame[4];let id=u64::from_le_bytes(frame[5..13].try_into().unwrap());let runtime=frame[13..29].try_into().unwrap();let generation=u64::from_le_bytes(frame[29..37].try_into().unwrap());let revision=u64::from_le_bytes(frame[37..45].try_into().unwrap());let hash:[u8;32]=frame[46..78].try_into().unwrap();let source=match frame[45]{0 if hash==[0;32]=>None,1=>Some(hash),_=>return Err(SessionError::Protocol)};let rest=&frame[HEADER..];let command=match opcode{1 if rest.len()==1=>Command::Open{kind:kind(rest[0])?,bytes:input.ok_or(SessionError::Protocol)?},2..=12 if rest.is_empty()&&input.is_none()=>match opcode{2=>Command::Close,3=>Command::Summary,4=>return Err(SessionError::Protocol),5=>Command::Plan,6=>Command::Preview,7=>Command::Apply,8=>Command::Verify,9=>Command::Export,10=>Command::Undo,11=>Command::Redo,_=>Command::Reset},4 if rest.len()==7&&input.is_none()=>Command::IndexPage{domain:domain(rest[0])?,offset:u32::from_le_bytes(rest[1..5].try_into().unwrap()),limit:u16::from_le_bytes(rest[5..7].try_into().unwrap())},13 if rest.len()==11&&input.is_none()=>Command::DetailPage{kind:detail_kind(rest[0])?,parent:u32::from_le_bytes(rest[1..5].try_into().unwrap()),offset:u32::from_le_bytes(rest[5..9].try_into().unwrap()),limit:u16::from_le_bytes(rest[9..11].try_into().unwrap())},_=>return Err(SessionError::Protocol)};Ok(Request{id,expected:Stamp{runtime,generation,revision,source},command})}
fn stamp(v:&mut Vec<u8>,s:Stamp){v.extend(s.runtime);v.extend(s.generation.to_le_bytes());v.extend(s.revision.to_le_bytes());v.push(u8::from(s.source.is_some()));v.extend(s.source.unwrap_or([0;32]));}
fn u32le(v:&mut Vec<u8>,n:u32){v.extend(n.to_le_bytes())}fn range(v:&mut Vec<u8>,r:&std::ops::Range<usize>){let(a,b)=span_bounds(r);u32le(v,a);u32le(v,b)}
fn summary(v:&mut Vec<u8>,s:&Summary){v.push(kind_code(s.kind));v.push(match s.version{None=>0,Some(Version::V300)=>1,Some(Version::V301)=>2});for n in [s.source_bytes,s.archive_entries,s.documents,s.logical_nodes]{u32le(v,n)}for &n in &s.counts{u32le(v,n)}u32le(v,s.collection_deprecated);v.push(u8::from(s.collection_version.is_some()));if let Some(c)=&s.collection_version{u32le(v,c.id);v.extend(c.number.to_le_bytes());range(v,&c.span)}v.extend(s.schema_sha256);v.push(u8::from(s.writer_enabled));}
fn row(v:&mut Vec<u8>,r:&Row){match r{Row::Slot(m)=>{v.push(match &m.state{ModelState::Achievement{..}=>1,ModelState::Counter{..}=>2});u32le(v,m.id);for x in m.guid{u32le(v,x)}for s in &m.fields{range(v,&s.bytes)}match &m.state{ModelState::Achievement{complete,current,completed}=>{v.push(u8::from(*complete));v.extend(current.to_bits().to_le_bytes());v.push(u8::from(completed.is_some()));if let Some((s,n))=completed{v.extend(s.to_le_bytes());u32le(v,*n)}},ModelState::Counter{current,counted_values,counted_guids}=>{v.extend(current.to_bits().to_le_bytes());v.push(u8::from(counted_values.is_some()));if let Some(n)=counted_values{u32le(v,*n as u32)}u32le(v,*counted_guids as u32);}}},Row::Collection(c)=>{v.push(3);v.extend(c.id.to_le_bytes());v.extend(c.ticks.to_le_bytes());range(v,&c.value);range(v,&c.pair)},Row::Celebration(c)=>{v.push(4);u32le(v,c.id);range(v,&c.bytes);u32le(v,c.guid_count as u32)},Row::AccountAchievement(a)=>{v.push(5);v.extend(a.guid);v.push(u8::from(a.complete));v.extend(a.current.to_bits().to_le_bytes());let b=a.completed.as_deref().unwrap_or("").as_bytes();v.push(b.len() as u8);v.extend(b);for r in &a.fields{range(v,r)}},Row::AccountCounter(c)=>{v.push(6);v.extend(c.guid);v.extend(c.current.to_bits().to_le_bytes());range(v,&c.field)},Row::Inventory(r)=>{v.push(7);u32le(v,r.id);for x in [r.item_id,r.unique_id,r.quantity]{v.push(u8::from(x.is_some()));if let Some(n)=x{v.extend(n.to_le_bytes());}}for f in &r.fields{v.push(u8::from(f.is_some()));if let Some(f)=f{range(v,f)}}v.push(match r.unique_is_nil{None=>0,Some(false)=>1,Some(true)=>2});},Row::Deprecated(c)=>{v.push(8);for w in c.guid{u32le(v,w)}v.extend(c.ticks.to_le_bytes());range(v,&c.value);range(v,&c.pair)}}}
fn error(e:SessionError)->(u8,u8){match e{SessionError::Foreign=>(1,0),SessionError::Replay=>(2,0),SessionError::Stale=>(3,0),SessionError::NoOpen=>(4,0),SessionError::NoDomain=>(5,0),SessionError::Range=>(6,0),SessionError::Unsupported=>(7,0),SessionError::Overflow=>(8,0),SessionError::Protocol=>(9,0),SessionError::Input(e)=>(10,match e{Error::Budget=>1,Error::Truncated=>2,Error::InvalidDistance=>3,Error::LengthMismatch=>4,Error::Overflow=>5,Error::InvalidToken=>6,Error::Schema=>7,Error::Version=>8,Error::Marker=>9,Error::Duplicate=>10,Error::Trailing=>11})}}
pub fn encode_reply(r:Reply)->Vec<u8>{let mut out=Vec::with_capacity(256);out.extend(MAGIC);out.extend(r.id.to_le_bytes());stamp(&mut out,r.stamp);match r.result{Err(e)=>{let(a,b)=error(e);out.extend([0,a,b])},Ok(p)=>{out.push(1);match p{Payload::Opened(s)=>{out.push(1);summary(&mut out,&s)},Payload::Closed=>out.push(2),Payload::Summary(s)=>{out.push(3);summary(&mut out,&s)},Payload::Page(p)=>{out.push(4);out.push(domain_code(p.domain));u32le(&mut out,p.total);u32le(&mut out,p.offset);out.extend((p.rows.len() as u16).to_le_bytes());for r in &p.rows{row(&mut out,r)}},Payload::Detail(p)=>{out.push(5);out.push(detail_code(p.kind));u32le(&mut out,p.parent);out.push(u8::from(p.is_null));u32le(&mut out,p.total);u32le(&mut out,p.offset);out.extend((p.rows.len() as u16).to_le_bytes());for r in p.rows{match r{DetailRow::Guid{words,span}=>{out.push(1);for w in words{u32le(&mut out,w)}range(&mut out,&span)},DetailRow::Text{utf8_len,digest,span}=>{out.push(2);u32le(&mut out,utf8_len);out.extend(digest);range(&mut out,&span)}}}}}}}debug_assert!(out.len()<=MAX_REPLY);out}
/// ABI validation failures are non-dispatched; valid same-runtime requests consume their ID even on error.
pub fn dispatch_frame(session:&mut ProductSession,frame:&[u8],input:Option<Vec<u8>>)->Result<Vec<u8>,SessionError>{let r=parse(frame,input)?;Ok(encode_reply(session.dispatch(r)))}
